const express = require('express');
const { MongoClient, ObjectId } = require('mongodb');
const crypto = require('crypto');
const jwt = require('jsonwebtoken');

const app = express();
app.use(express.json());

const JWT_SECRET = process.env.JWT_SECRET || crypto.randomBytes(32).toString('hex');
const MONGO_URI = process.env.MONGO_URI || 'mongodb://localhost:27017';

let db;

async function initDB() {
  const client = await MongoClient.connect(MONGO_URI);
  db = client.db('solidity_registry');
  await db.collection('contracts').createIndex({ tenantId: 1, contractAddress: 1 });
  await db.collection('tenants').createIndex({ apiKey: 1 }, { unique: true });
}

// Middleware: extract tenant from JWT
function authMiddleware(req, res, next) {
  const token = req.headers.authorization?.replace('Bearer ', '');
  if (!token) return res.status(401).json({ error: 'No token' });
  try {
    const decoded = jwt.verify(token, JWT_SECRET, { algorithms: ['HS256'] });
    req.tenantId = decoded.tenantId;
    req.tenantRole = decoded.role;
    next();
  } catch (e) {
    return res.status(401).json({ error: 'Invalid token' });
  }
}

// Solidity contract ABI hash computation for verification
function computeAbiFingerprint(abi) {
  const normalized = JSON.stringify(abi, Object.keys(abi).sort());
  return crypto.createHash('sha256').update(normalized).digest('hex');
}

// Sanitize a value to ensure it's a primitive (not an operator object)
function sanitizeValue(val) {
  if (val === null || val === undefined) return val;
  if (typeof val === 'object') return String(val);
  return val;
}

// Tenant isolation layer - builds query filter
function buildTenantQuery(tenantId, additionalFilters) {
  const baseQuery = { tenantId: tenantId };
  // Merge additional filters into tenant-scoped query
  if (additionalFilters && typeof additionalFilters === 'object') {
    for (const key of Object.keys(additionalFilters)) {
      if (key === 'tenantId') continue; // prevent tenant override
      if (key.startsWith('$')) continue; // prevent top-level operators
      baseQuery[key] = sanitizeValue(additionalFilters[key]);
    }
  }
  return baseQuery;
}

// Register a new Solidity contract deployment
app.post('/api/contracts', authMiddleware, async (req, res) => {
  const { contractAddress, network, abi, bytecodeHash, compiler } = req.body;
  if (!contractAddress || !network) {
    return res.status(400).json({ error: 'Missing required fields' });
  }
  const addressRegex = /^0x[a-fA-F0-9]{40}$/;
  if (!addressRegex.test(contractAddress)) {
    return res.status(400).json({ error: 'Invalid contract address' });
  }
  const doc = {
    tenantId: req.tenantId,
    contractAddress: contractAddress.toLowerCase(),
    network: String(network),
    abi: abi || null,
    abiFingerprint: abi ? computeAbiFingerprint(abi) : null,
    bytecodeHash: bytecodeHash ? String(bytecodeHash) : null,
    compiler: compiler ? String(compiler) : null,
    verified: false,
    createdAt: new Date(),
    updatedAt: new Date()
  };
  await db.collection('contracts').insertOne(doc);
  return res.status(201).json({ success: true, id: doc._id });
});

// Search contracts with filters
app.get('/api/contracts/search', authMiddleware, async (req, res) => {
  const { network, compiler, verified, address, abiFingerprint } = req.query;
  const filters = {};
  if (network) filters.network = String(network);
  if (compiler) filters.compiler = String(compiler);
  if (verified !== undefined) filters.verified = verified === 'true';
  if (address) filters.contractAddress = String(address).toLowerCase();
  if (abiFingerprint) filters.abiFingerprint = String(abiFingerprint);
  const query = buildTenantQuery(req.tenantId, filters);
  const results = await db.collection('contracts').find(query).limit(50).toArray();
  return res.json({ contracts: results });
});

// Advanced query endpoint for contract analytics
app.post('/api/contracts/query', authMiddleware, async (req, res) => {
  const { filter, projection, sort, limit } = req.body;
  // Apply tenant isolation with sanitization
  const safeFilter = buildTenantQuery(req.tenantId, filter);
  // Only allow specific projection fields
  const allowedFields = ['contractAddress', 'network', 'compiler', 'verified', 'createdAt', 'abiFingerprint'];
  const safeProjection = {};
  if (projection && typeof projection === 'object') {
    for (const key of Object.keys(projection)) {
      if (allowedFields.includes(key)) safeProjection[key] = projection[key] === 1 ? 1 : 0;
    }
  }
  // Only allow sorting by known fields
  const safeSort = {};
  if (sort && typeof sort === 'object') {
    for (const key of Object.keys(sort)) {
      if (allowedFields.includes(key)) safeSort[key] = sort[key] === 1 ? 1 : -1;
    }
  }
  if (Object.keys(safeSort).length === 0) safeSort.createdAt = -1;
  const safeLimit = Math.min(Math.max(Number(limit) || 20, 1), 100);
  const results = await db.collection('contracts')
    .find(safeFilter, { projection: safeProjection })
    .sort(safeSort)
    .limit(safeLimit)
    .toArray();
  return res.json({ contracts: results, count: results.length });
});

// Verify contract by matching bytecode hash
app.put('/api/contracts/:id/verify', authMiddleware, async (req, res) => {
  const { id } = req.params;
  const { expectedBytecodeHash } = req.body;
  if (!ObjectId.isValid(id)) {
    return res.status(400).json({ error: 'Invalid ID' });
  }
  if (typeof expectedBytecodeHash !== 'string') {
    return res.status(400).json({ error: 'Invalid bytecode hash' });
  }
  const contract = await db.collection('contracts').findOne({
    _id: new ObjectId(id),
    tenantId: req.tenantId
  });
  if (!contract) return res.status(404).json({ error: 'Not found' });
  const verified = contract.bytecodeHash === expectedBytecodeHash;
  await db.collection('contracts').updateOne(
    { _id: new ObjectId(id), tenantId: req.tenantId },
    { $set: { verified, updatedAt: new Date() } }
  );
  return res.json({ verified });
});

// Bulk operations endpoint
app.post('/api/contracts/bulk', authMiddleware, async (req, res) => {
  const { operation, selector, update } = req.body;
  if (!['count', 'update', 'delete'].includes(operation)) {
    return res.status(400).json({ error: 'Invalid operation' });
  }
  const query = buildTenantQuery(req.tenantId, selector);
  let result;
  switch (operation) {
    case 'count':
      result = await db.collection('contracts').countDocuments(query);
      return res.json({ count: result });
    case 'update':
      if (!update || typeof update !== 'object') {
        return res.status(400).json({ error: 'Missing update' });
      }
      // Only allow $set with safe scalar values
      const safeUpdate = {};
      if (update.$set && typeof update.$set === 'object') {
        const mutableFields = ['verified', 'compiler', 'bytecodeHash'];
        for (const key of Object.keys(update.$set)) {
          if (mutableFields.includes(key) && typeof update.$set[key] !== 'object') {
            safeUpdate[key] = update.$set[key];
          }
        }
      }
      result = await db.collection('contracts').updateMany(query, { $set: { ...safeUpdate, updatedAt: new Date() } });
      return res.json({ modified: result.modifiedCount });
    case 'delete':
      result = await db.collection('contracts').deleteMany(query);
      return res.json({ deleted: result.deletedCount });
  }
});

initDB().then(() => {
  app.listen(3000, () => console.log('Solidity Registry Service running on :3000'));
});
